      switch (json['approved']) {
        true => ChatToolCallApprovedAction.fromJson(json),
        false => ChatToolCallDeniedAction.fromJson(json),
        _ => throw FormatException(
          'Invalid ChatToolCallConfirmedAction: ${json['approved']}',
        ),
      };

  /// The `approved` values this version decodes to a known member.
  static const discriminatorValues = <bool>{true, false};

  /// The `approved` discriminator.
  bool get approved;

  /// Turn identifier
  String get turnId;

  /// Tool call identifier
  String get toolCallId;

  /// Additional provider-specific metadata for this tool call.
  ///
  /// Clients MAY look for well-known keys here to provide enhanced UI.
  /// For example, a `ptyTerminal` key with `{ input: string; output: string }`
  /// indicates the tool operated on a terminal (both `input` and `output` may
  /// contain escape sequences).
  JsonMap? get meta;

  /// ID of the selected confirmation option, if the server provided options
  String? get selectedOptionId;

  /// Encodes this as JSON.
  @override
  JsonMap toJson();
}

